 const form=document.querySelector('#manualForm');bindEnhancedInputs(form);const update=()=>{const total=parseLocalAmount(form.totalAmount.value);document.querySelector('#manualInstallment').value=total?formatLocalAmount(form.due2.value?total/2:total):''};form.totalAmount.oninput=update;form.due2.onchange=update;
