const normalizeText=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const pdfDate=value=>{const m=value?.match(/(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})/);if(!m)return'';return `${m[3].length===2?'20'+m[3]:m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`};
const pdfAmount=value=>{if(!value)return'';let s=value.replace(/[^\d.,]/g,'');if(s.includes(',')&&s.includes('.'))s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replaceAll('.','').replace(',','.'):s.replaceAll(',','');else if(s.includes(','))s=s.replace(',','.');return Number(s)||''};
function obligationFromPdf(text,target){if(target)return target;const s=normalizeText(text);const aliases=[['Ingresos Brutos',['ingresos brutos','iibb']],['IVA',['impuesto al valor agregado','iva']],['ATM',['administracion tributaria mendoza']],['EDEMSA local',['edemsa']],['Ecogas',['ecogas']],['Celular',['telefonia movil','celular']],['Internet local - Punto Net',['punto net','puntonet']],['Movistar Fibra casa',['movistar fibra']],['Sistema Flexxus',['flexxus']],['Colegio Giovani',['giovani']],['Municipalidad casa',['municipalidad']],['Seguro local',['seguro','poliza']],['Honorarios contador',['honorarios']]];return aliases.find(([,words])=>words.some(word=>s.includes(word)))?.[0]||''}
async function extractPdf(file){const pdf=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;const pages=[];for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n);const content=await page.getTextContent();pages.push(content.items.map(item=>item.str).join(' '))}return pages.join('\n')}
function pdfDraft(text,target,fileName){
 const s=text.replace(/\s+/g,' ');const dates=[...s.matchAll(/\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}/g)].map(x=>x[0]);const issued=s.match(/emisi[oó]n\s*[:\-]?\s*(\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4})/i)?.[1]||dates[0];
 const labeled=[...s.matchAll(/(?:primer|segundo|1(?:er|ro|°)?|2(?:do|°)?)?\s*vencimiento\s*[:\-]?\s*(\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4})/gi)].map(x=>x[1]);
 const obligation=obligationFromPdf(s,target);const isEdemsa=obligation.startsWith('EDEMSA');const candidates=labeled.length?labeled:dates.filter(date=>date!==issued);const due=pdfDate(isEdemsa&&candidates.length>1?candidates.at(-2):candidates.at(-1)||dates.at(-1));const due2=isEdemsa&&candidates.length>1?pdfDate(candidates.at(-1)):'';
 const total=pdfAmount(s.match(/(?:total\s+(?:a\s+)?pagar|importe\s+total|total)\s*[:$ ]+([\d.,]+)/i)?.[1]);
 return {obligation,period:s.match(/per[ií]odo\s*[:\-]?\s*(\d{1,2}[\/-]\d{4})/i)?.[1]?.replace('-','/')||(due?`${due.slice(5,7)}/${due.slice(0,4)}`:''),due,due2,issued:pdfDate(issued),totalAmount:total,amount:due2&&total?total/2:total,currency:/\bUSD\b|U\$S|D[OÓ]LAR/i.test(s)?'USD':'ARS',invoice:s.match(/(?:factura|comprobante|n[º°ro.]*)\s*[:\-]?\s*([A-Z]?\s*\d{1,5}[- ]\d{4,12})/i)?.[1]?.replace(/\s/g,'')||'',notes:`Importado desde ${fileName}`}
}
