async function handleDocument(file){const target=localStorage.getItem('cv_upload_target')||'';localStorage.removeItem('cv_upload_target');if(file.size>15*1024*1024){toast('El archivo supera el máximo de 15 MB.');return}if(file.type!=='application/pdf'){toast('La extracción automática está disponible para PDF.');openManualForm(target);return}toast(`Analizando ${file.name}…`);try{const text=await extractPdf(file);if(!text.trim())throw new Error('No se detectó texto');openPdfReview(pdfDraft(text,target,file.name));toast('Datos visibles. Revisalos y guardá el vencimiento.')}catch(error){console.error(error);toast('El PDF es una imagen escaneada. Completá los datos manualmente.');openManualForm(target)}}
