function editRecord(id){const record=appState.records.find(item=>String(item.id)===String(id));if(!record)return;const options=obligations.filter(item=>item.active!==false||item.name===record.obligation).map(item=>`<option value="${safe(item.name)}" ${item.name===record.obligation?'selected':''}>${safe(item.name)}</option>`).join('');document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal form-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">EDITAR IMPUESTO</span><h2>${safe(record.obligation)}</h2><form id="editRecordForm"><label class="wide">Obligación<select name="obligation" required>${options}</select></label><label>Período<input name="period" required value="${safe(record.period)}"></label><label>Vencimiento${editableDateInput('due',record.due,true)}</label><label>Importe<input name="amount" type="text" inputmode="decimal" data-money-input required value="${record.amount??''}"></label><label>Moneda<select name="currency"><option ${record.currency==='ARS'?'selected':''}>ARS</option><option ${record.currency==='USD'?'selected':''}>USD</option></select></label><label class="wide">Número de factura<input name="invoice" value="${safe(record.invoice||'')}"></label><label class="wide">Observaciones<textarea name="notes" rows="3">${safe(record.notes||'')}</textarea></label><div class="form-actions wide"><button type="button" class="outline" data-close>Cancelar</button><button type="submit" class="primary">Guardar cambios</button></div></form></section></div>`;document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);const form=document.querySelector('#editRecordForm');bindEnhancedInputs(form);form.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const obligation=obligations.find(item=>item.name===data.obligation);const amount=parseLocalAmount(data.amount);Object.assign(record,{obligation:data.obligation,category:obligation?.category||record.category,period:data.period,due:parseDateInput(data.due),amount,totalAmount:amount,currency:data.currency,invoice:data.invoice,notes:data.notes});if(record.status!=='paid')record.status=statusFor(record.due);closeModal();render();toast('Impuesto actualizado')}}
function editObligation(id){
 const obligation=obligations.find(o=>String(o.id)===String(id));if(!obligation)return;
 document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal form-modal obligation-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">MI AGENDA</span><h2>Editar obligación</h2><form id="editObligationForm"><label class="wide">Nombre<input name="name" required value="${safe(obligation.name)}"></label><label class="wide">Categoría<select name="category">${['Impuestos','Servicios','Comunicaciones','Alquileres','Seguros','Educación','Software','Otro'].map(category=>`<option ${category===obligation.category?'selected':''}>${category}</option>`).join('')}</select></label><div class="form-actions wide"><button type="button" class="outline" data-close>Cancelar</button><button type="submit" class="primary">Guardar cambios</button></div></form></section></div>`;
 document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()};document.querySelector('#editObligationForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const newName=data.name.trim();if(obligations.some(o=>o!==obligation&&normalizeText(o.name)===normalizeText(newName))){toast('Ya existe una obligación con ese nombre');return}const oldName=obligation.name;obligation.name=newName;obligation.category=data.category;appState.records.filter(r=>r.obligation===oldName).forEach(r=>{r.obligation=newName;r.category=data.category});persistUserData();closeModal();render();toast('Obligación actualizada')};
}
