function bindFuelAmountCalculation(form){
 const priceInput=form?.elements.pricePerLiter;const totalInput=form?.elements.totalAmount;const litersInput=form?.elements.liters;
 if(!priceInput||!totalInput||!litersInput)return;
 const calculate=()=>{const price=parseLocalAmount(priceInput.value);const total=parseLocalAmount(totalInput.value);litersInput.value=price>0&&total>0?(total/price).toFixed(3).replace(/\.?0+$/,''):''};
 ['input','change','moneychange'].forEach(eventName=>{priceInput.addEventListener(eventName,calculate);totalInput.addEventListener(eventName,calculate)});calculate();
}

let routeMap=null;let routePreview=null;let routePickMode='';let lastGeocodeRequest=0;const routeSearchPoints={from:null,to:null};
async function findOpenLocation(query){const coordinateMatch=query.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/);if(coordinateMatch)return {lat:Number(coordinateMatch[1]),lon:Number(coordinateMatch[2]),label:query,query:normalizeText(query)};const cache=JSON.parse(localStorage.getItem('impueston_geocode_cache_v1')||'{}');const key=normalizeText(query);if(cache[key])return {...cache[key],query:key};const wait=Math.max(0,1100-(Date.now()-lastGeocodeRequest));if(wait)await new Promise(resolve=>setTimeout(resolve,wait));lastGeocodeRequest=Date.now();const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&accept-language=es&q=${encodeURIComponent(query)}`);if(!response.ok)throw new Error('No se pudo localizar la dirección');const [result]=await response.json();if(!result)throw new Error(`No se encontró ${query}`);const point={lat:Number(result.lat),lon:Number(result.lon),label:result.display_name};cache[key]=point;localStorage.setItem('impueston_geocode_cache_v1',JSON.stringify(cache));return {...point,query:key}}
function initializeRouteMap(){const container=document.querySelector('#routeMap');if(!container)return;if(routeMap)routeMap.remove();routeMap=L.map(container,{zoomControl:false,scrollWheelZoom:true,doubleClickZoom:true,touchZoom:true}).setView([-34.6,-64.2],4);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(routeMap);if(routePreview){const line=L.geoJSON(routePreview.geometry,{style:{color:'#0872ed',weight:5,opacity:.9}}).addTo(routeMap);routeMap.fitBounds(line.getBounds(),{padding:[28,28]})}const points=routePreview?{from:routePreview.from,to:routePreview.to}:routeSearchPoints;[['from','Origen','#0872ed'],['to','Destino','#08a66a']].forEach(([key,label,color])=>{const point=points[key];if(point)L.circleMarker([point.lat,point.lon],{radius:7,color,fillColor:'#fff',fillOpacity:1,weight:3}).bindTooltip(label).addTo(routeMap)});if(!routePreview){const visible=Object.values(routeSearchPoints).filter(Boolean);if(visible.length===1)routeMap.setView([visible[0].lat,visible[0].lon],14);if(visible.length===2)routeMap.fitBounds(visible.map(point=>[point.lat,point.lon]),{padding:[40,40]})}routeMap.on('click',event=>{if(!routePickMode)return;const form=document.querySelector('#routeForm');if(!form)return;const value=`${event.latlng.lat.toFixed(5)}, ${event.latlng.lng.toFixed(5)}`;form.elements[routePickMode].value=value;const mapInput=document.querySelector(`[data-map-route-input="${routePickMode}"]`);if(mapInput)mapInput.value=value;routeSearchPoints[routePickMode]={lat:event.latlng.lat,lon:event.latlng.lng,label:value,query:normalizeText(value)};routePreview=null;routePickMode='';initializeRouteMap();toast('Punto marcado en el mapa');if(routeSearchPoints.from&&routeSearchPoints.to)setTimeout(()=>document.querySelector('#calculateOpenRoute')?.click(),0)});container.classList.toggle('is-picking',Boolean(routePickMode));setTimeout(()=>routeMap?.invalidateSize(),0)}
async function calculateOpenRouteDistance(origin,destination){
 const from=routeSearchPoints.from?.query===normalizeText(origin)?routeSearchPoints.from:await findOpenLocation(origin);const to=routeSearchPoints.to?.query===normalizeText(destination)?routeSearchPoints.to:await findOpenLocation(destination);routeSearchPoints.from=from;routeSearchPoints.to=to;const response=await fetch(`https://router.project-osrm.org/route/v1/driving/${from.lon},${from.lat};${to.lon},${to.lat}?overview=full&geometries=geojson&steps=false`);if(!response.ok)throw new Error('No se pudo calcular la ruta');const data=await response.json();const route=data.routes?.[0];if(data.code!=='Ok'||!route)throw new Error('No se encontró una ruta entre esos puntos');return {distance:route.distance/1000,duration:route.duration,from,to,geometry:route.geometry}
}

const fuelViewBeforeAutomaticLiters=enhancedFuel;
enhancedFuel=function(){
 return fuelViewBeforeAutomaticLiters()
  .replace('Para calcular el consumo, cargá siempre el kilometraje y los litros al llenar nuevamente el tanque.','Ingresá el precio por litro y el monto total. Los litros cargados se calculan automáticamente.')
  .replace('<label>Litros cargados<input name="liters" type="number" min="0.01" step="0.01" required placeholder="Ej. 45,5"></label><label>Precio por litro<input name="pricePerLiter" type="number" min="0.01" step="0.01" required placeholder="Ej. 1250"></label>','<label>Precio por litro<input name="pricePerLiter" type="text" inputmode="decimal" data-money-input required placeholder="Ej. 2.139,00"></label><label>Monto total cargado<input name="totalAmount" type="text" inputmode="decimal" data-money-input required placeholder="Ej. 50.000,00"></label><label>Litros calculados<input name="liters" type="number" min="0.001" step="0.001" required readonly placeholder="Se calcula automáticamente"></label>')
  .replace('<button class="primary" type="submit">＋ Calcular y agregar</button>','<button class="outline open-route-button" id="calculateOpenRoute" type="button">🗺️ Calcular km automáticamente</button><button class="primary" type="submit">＋ Calcular gasto y agregar</button><small class="route-map-credit">Ruta basada en datos © OpenStreetMap · cálculo OSRM</small>')
  .replace('</section><section class="route-summary">','</section><section class="panel route-map-panel"><div class="panel-head"><div><span class="eyebrow">MAPA DE LA RUTA</span><h2>Buscá y calculá tu recorrido</h2></div><small>Mové el mapa y usá la rueda, doble toque o pellizco para acercar</small></div><div class="route-map-shell"><div class="route-map-search"><div class="route-map-search-title"><b>¿A dónde vas?</b></div><label><i class="origin"></i><input data-map-route-input="from" placeholder="Origen: dirección o localidad"></label><label><i class="destination"></i><input data-map-route-input="to" placeholder="Destino: dirección o localidad"></label><div class="route-map-search-actions"><button class="outline route-map-swap" id="mapRouteSwap" type="button" title="Invertir origen y destino">⇅ <span>Invertir</span></button><button class="outline" id="mapPickOrigin" type="button">⌖ Marcar</button><button class="primary" id="mapSearchRoute" type="button">Ruta y gasto</button></div></div><div id="routeMap" aria-label="Mapa del recorrido"></div></div></section><section class="route-summary">');
}

editFuelEntry=function(id){
 const entry=appState.fuelEntries.find(item=>String(item.id)===String(id));if(!entry)return;
 const total=Number(entry.liters||0)*Number(entry.pricePerLiter||0);
 document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal form-modal"><button class="modal-close" data-close>×</button><span class="modal-kicker">EDITAR CARGA</span><h2>${safe(entry.vehicle)}</h2><form id="editFuelForm"><label>Vehículo<input name="vehicle" required value="${safe(entry.vehicle)}"></label><label>Estación de servicio<input name="station" value="${safe(entry.station||'')}" placeholder="Ej. YPF Centro"></label><label>Fecha${editableDateInput('date',entry.date,true)}</label><label>Kilometraje<input name="odometer" type="number" min="0" step="1" required value="${entry.odometer}"></label><label>Precio por litro<input name="pricePerLiter" type="text" inputmode="decimal" data-money-input required value="${entry.pricePerLiter}"></label><label>Monto total cargado<input name="totalAmount" type="text" inputmode="decimal" data-money-input required value="${total}"></label><label>Litros calculados<input name="liters" type="number" min="0.001" step="0.001" required readonly value="${entry.liters}"></label><div class="form-actions wide"><button type="button" class="outline" data-close>Cancelar</button><button type="submit" class="primary">Guardar cambios</button></div></form></section></div>`;
 document.querySelectorAll('[data-close]').forEach(button=>button.onclick=closeModal);document.querySelector('.modal-backdrop').onclick=event=>{if(event.target.classList.contains('modal-backdrop'))closeModal()};
 const form=document.querySelector('#editFuelForm');bindEnhancedInputs(form);bindFuelAmountCalculation(form);
 form.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const vehicle=data.vehicle.trim();const odometer=Number(data.odometer);const pricePerLiter=parseLocalAmount(data.pricePerLiter);const liters=Number(data.liters);const duplicate=appState.fuelEntries.find(item=>String(item.id)!==String(entry.id)&&item.vehicle.toLowerCase()===vehicle.toLowerCase()&&Number(item.odometer)===odometer);if(duplicate){toast('Ya existe una carga de ese vehículo con el mismo kilometraje');return}if(!Number.isFinite(liters)||liters<=0||pricePerLiter<=0){toast('Ingresá un precio por litro y una cantidad de litros válidos');return}Object.assign(entry,{vehicle,station:data.station.trim(),date:parseDateInput(data.date),odometer,liters,pricePerLiter});persistUserData();closeModal();render();toast('Carga actualizada')};
}

const bindBeforeAutomaticFuelLiters=bind;
bind=function(){
 bindBeforeAutomaticFuelLiters();
 initializeRouteMap();
 const routeButton=document.querySelector('#calculateOpenRoute');const routeForm=document.querySelector('#routeForm');if(routeButton&&routeForm)routeButton.onclick=async()=>{const origin=routeForm.elements.from.value.trim();const destination=routeForm.elements.to.value.trim();if(!origin||!destination){toast('Completá desde dónde salís y hasta dónde vas');return}routeButton.disabled=true;routeButton.textContent='Buscando la mejor ruta…';try{const route=await calculateOpenRouteDistance(origin,destination);routePreview=route;routeForm.elements.distance.value=route.distance.toFixed(1);initializeRouteMap();toast(`Ruta calculada: ${route.distance.toLocaleString('es-AR',{maximumFractionDigits:1})} km`)}catch(error){console.error(error);toast(error.message||'No se pudo calcular la ruta. Revisá las direcciones.')}finally{routeButton.disabled=false;routeButton.textContent='🗺️ Calcular km automáticamente'}};
 if(routeForm){routeForm.elements.from.placeholder='Ej. Godoy Cruz, Mendoza';routeForm.elements.to.placeholder='Ej. San Rafael, Mendoza';['from','to'].forEach(field=>{const input=routeForm.elements[field];const controls=document.createElement('div');controls.className='route-location-controls';controls.innerHTML=`<button class="primary route-search-button" type="button" data-locate-route="${field}">⌕ Buscar</button><button class="outline route-pick-button" type="button" data-pick-route="${field}" title="Elegir directamente sobre el mapa">⌖ Marcar</button>`;input.closest('label').append(controls);const result=document.createElement('small');result.className='route-location-result';result.dataset.routeResult=field;input.closest('label').append(result);input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();controls.querySelector('[data-locate-route]').click()}});input.addEventListener('input',()=>{routeSearchPoints[field]=null;routePreview=null;result.textContent=''})});const swap=document.createElement('button');swap.type='button';swap.className='outline route-swap-button';swap.textContent='⇅ Invertir origen y destino';routeButton.before(swap);swap.onclick=()=>{const fromValue=routeForm.elements.from.value;routeForm.elements.from.value=routeForm.elements.to.value;routeForm.elements.to.value=fromValue;const fromPoint=routeSearchPoints.from;routeSearchPoints.from=routeSearchPoints.to;routeSearchPoints.to=fromPoint;routePreview=null;initializeRouteMap();if(routeSearchPoints.from&&routeSearchPoints.to)routeButton.click()};document.querySelectorAll('[data-locate-route]').forEach(button=>button.onclick=async()=>{const field=button.dataset.locateRoute;const input=routeForm.elements[field];const query=input.value.trim();if(!query){input.focus();toast('Escribí una dirección o localidad');return}button.disabled=true;button.textContent='Buscando…';try{routeSearchPoints[field]=await findOpenLocation(query);routePreview=null;const result=document.querySelector(`[data-route-result="${field}"]`);if(result)result.textContent=`✓ ${routeSearchPoints[field].label}`;initializeRouteMap();toast(`${field==='from'?'Origen':'Destino'} encontrado`);if(routeSearchPoints.from&&routeSearchPoints.to)routeButton.click()}catch(error){console.error(error);toast(error.message||'No se encontró la ubicación')}finally{button.disabled=false;button.textContent='⌕ Buscar'}});document.querySelectorAll('[data-pick-route]').forEach(button=>button.onclick=()=>{routePickMode=button.dataset.pickRoute;initializeRouteMap();toast(`Tocá el mapa para marcar el ${routePickMode==='from'?'origen':'destino'}`)})}
 if(routeForm){const mapFrom=document.querySelector('[data-map-route-input="from"]');const mapTo=document.querySelector('[data-map-route-input="to"]');const syncMapInputs=()=>{routeForm.elements.from.value=mapFrom.value.trim();routeForm.elements.to.value=mapTo.value.trim()};[mapFrom,mapTo].forEach(input=>input?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();document.querySelector('#mapSearchRoute')?.click()}}));document.querySelector('#mapSearchRoute')?.addEventListener('click',async event=>{syncMapInputs();const button=event.currentTarget;if(!mapFrom.value.trim()||!mapTo.value.trim()){(!mapFrom.value.trim()?mapFrom:mapTo).focus();toast('Completá origen y destino');return}button.disabled=true;button.textContent='Buscando…';try{routeSearchPoints.from=await findOpenLocation(mapFrom.value.trim());routeSearchPoints.to=await findOpenLocation(mapTo.value.trim());routeForm.elements.from.value=mapFrom.value.trim();routeForm.elements.to.value=mapTo.value.trim();routeButton.click()}catch(error){console.error(error);toast(error.message||'No se encontró la ubicación')}finally{button.disabled=false;button.textContent='Ruta y gasto'}});document.querySelector('#mapRouteSwap')?.addEventListener('click',()=>{const value=mapFrom.value;mapFrom.value=mapTo.value;mapTo.value=value;syncMapInputs();swap.click()});document.querySelector('#mapPickOrigin')?.addEventListener('click',event=>{routePickMode=routeSearchPoints.from?'to':'from';initializeRouteMap();event.currentTarget.textContent=routePickMode==='from'?'Tocá el mapa para marcar origen':'Tocá el mapa para marcar destino';toast(event.currentTarget.textContent)});routeForm.elements.from.closest('label').classList.add('route-form-location-field');routeForm.elements.to.closest('label').classList.add('route-form-location-field')}
 const fuelForm=document.querySelector('#fuelForm');if(!fuelForm)return;
 bindEnhancedInputs(fuelForm);bindFuelAmountCalculation(fuelForm);
 fuelForm.onsubmit=event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const vehicle=data.vehicle.trim();const odometer=Number(data.odometer);const pricePerLiter=parseLocalAmount(data.pricePerLiter);const liters=Number(data.liters);const previous=appState.fuelEntries.filter(item=>item.vehicle.toLowerCase()===vehicle.toLowerCase()).sort((a,b)=>b.odometer-a.odometer)[0];if(previous&&odometer<=previous.odometer){toast(`El kilometraje debe ser mayor a ${previous.odometer.toLocaleString('es-AR')} km`);return}if(!Number.isFinite(liters)||liters<=0||pricePerLiter<=0){toast('Ingresá un precio por litro y una cantidad de litros válidos');return}appState.fuelEntries.push({id:newUuid(),vehicle,station:data.station.trim(),date:data.date,odometer,liters,pricePerLiter});persistUserData();render();toast(previous?'Carga guardada y consumo calculado':'Carga inicial guardada')};
}

function ensureExtraCategories(){document.querySelectorAll('select[name="category"]').forEach(select=>{['Salud','Tarjetas'].forEach(category=>{if([...select.options].some(option=>option.value===category))return;const option=document.createElement('option');option.value=category;option.textContent=category;const other=[...select.options].find(item=>item.value==='Otro'||item.value==='Otros');other?select.insertBefore(option,other):select.append(option)})})}
const categoryOptionsObserver=new MutationObserver(ensureExtraCategories);categoryOptionsObserver.observe(document.querySelector('#app'),{childList:true,subtree:true});ensureExtraCategories();

if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(registration=>registration.update()).catch(error=>console.warn('No se pudo actualizar la aplicación',error));
supabase?.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY'){passwordRecoveryActive=true;setTimeout(()=>resetPasswordScreen(),0)}});
await startApp();
